// Exercise completion printing, native setup, and Bash dynamic suggestions.
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import {
  mkdtemp,
  mkdir,
  readFile,
  writeFile,
  chmod,
  rm,
  readdir,
} from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { gunzipSync } from 'node:zlib';
const execute = promisify(execFile);
const quote = value => `'${value.replace(/'/g, "'\\''")}'`;
const posix = value =>
  value
    .replace(/\\/g, '/')
    .replace(/^([a-z]):\//i, (_, drive) => `/${drive.toLowerCase()}/`);
const platform = `${process.platform === 'win32' ? 'win' : process.platform}-${process.arch}`;
const archive = await readFile(
  resolve(
    'dist-bin',
    `craft-${platform}${process.platform === 'win32' ? '.exe' : '.gz'}`,
  ),
);
const root = await mkdtemp(join(tmpdir(), 'craft setup smoke '));
try {
  const binary = join(
    root,
    process.platform === 'win32' ? 'craft.exe' : 'craft',
  );
  await writeFile(
    binary,
    process.platform === 'win32' ? archive : gunzipSync(archive),
  );
  await chmod(binary, 0o755);
  const env = {
    ...process.env,
    HOME: root,
    USERPROFILE: root,
    XDG_DATA_HOME: join(root, 'share'),
    XDG_CONFIG_HOME: join(root, 'config'),
    CRAFT_WORKSPACE: '',
    CRAFT_CONFIG: '',
    CRAFT_DRY_RUN: '',
    DRY_RUN: '',
    NODE_OPTIONS: '',
  };
  const run = (args, extra = {}) =>
    execute(binary, args, {
      cwd: root,
      env: { ...env, ...extra },
      timeout: 30000,
    });
  for (const shell of ['bash', 'zsh', 'fish']) {
    assert.match(
      (await run(['completion', shell])).stdout,
      /--get-yargs-completions/,
    );
    assert.match(
      (
        await execute(
          process.execPath,
          [resolve('packed/dist/craft'), 'completion', shell],
          { cwd: root, env },
        )
      ).stdout,
      /sentry-craft/,
    );
  }
  const files = await readdir(root);
  await run(['setup', '--shell', 'bash', '--dry-run']);
  assert.deepEqual(await readdir(root), files);
  await mkdir(join(root, '.agents'));
  await mkdir(join(root, '.claude'));
  await run(['setup', '--no-agent-skills', '--no-completions']);
  await run(['setup', '--no-completions']);
  await assert.rejects(
    readFile(join(root, '.agents/skills/craft-cli/SKILL.md')),
    { code: 'ENOENT' },
  );
  await run(['setup', '--agent-skills', '--no-completions']);
  const pkg = JSON.parse(await readFile('package.json', 'utf8'));
  for (const agent of ['.agents', '.claude']) {
    const installed = await readFile(
      join(root, agent, 'skills/craft-cli/SKILL.md'),
      'utf8',
    );
    assert(
      installed.includes(`version: ${JSON.stringify(pkg.version)}`),
      'Skill must use the binary version',
    );
    assert.match(installed, /craft publish/);
  }
  const npmHome = join(root, 'npm home');
  await mkdir(join(npmHome, '.agents'), { recursive: true });
  await execute(
    process.execPath,
    [resolve('packed/dist/craft'), 'setup', '--no-completions'],
    {
      cwd: root,
      env: {
        ...env,
        HOME: npmHome,
        USERPROFILE: npmHome,
        XDG_DATA_HOME: join(npmHome, 'share'),
        XDG_CONFIG_HOME: join(npmHome, 'config'),
      },
      timeout: 30000,
    },
  );
  assert(
    (
      await readFile(join(npmHome, '.agents/skills/craft-cli/SKILL.md'), 'utf8')
    ).includes(`version: ${JSON.stringify(pkg.version)}`),
    'Portable JS must embed/install the version-pinned skill',
  );
  const profile = join(root, '.bashrc');
  await writeFile(profile, 'user profile');
  await run(['setup', '--shell', 'bash']);
  const script = join(root, 'share/bash-completion/completions/craft');
  assert.match(await readFile(script, 'utf8'), /Generated by Craft/);
  assert.equal(await readFile(profile, 'utf8'), 'user profile');
  const completion = await execute(
    'bash',
    [
      '-c',
      `source ${quote(posix(script))}; COMP_WORDS=(${quote(posix(binary))} setup --in); COMP_CWORD=2; _craft_completion; printf '%s\\n' "\${COMPREPLY[@]}"`,
    ],
    { cwd: root, env },
  );
  assert(
    completion.stdout.split(/\r?\n/).includes('--install-dir'),
    `Missing --install-dir: ${completion.stdout}`,
  );
  assert(
    completion.stdout.split(/\r?\n/).includes('--install'),
    `Missing --install: ${completion.stdout}`,
  );
  const middle = await execute(
    'bash',
    [
      '-c',
      `source ${quote(posix(script))}; COMP_WORDS=(${quote(posix(binary))} setup --sh --log-level Info); COMP_CWORD=2; _craft_completion; printf '%s\\n' "\${COMPREPLY[@]}"`,
    ],
    { cwd: root, env },
  );
  assert(
    middle.stdout.split(/\r?\n/).includes('--shell'),
    'Bash must complete the word at the cursor',
  );
  for (const shell of ['zsh', 'fish']) {
    try {
      await execute(shell, ['--version'], { env });
    } catch (error) {
      if (error.code !== 'ENOENT' || platform === 'linux-x64') throw error;
      continue;
    }
    const shellScript = join(root, `completion.${shell}`);
    await writeFile(shellScript, (await run(['completion', shell])).stdout);
    await execute(shell, ['-n', shellScript], { env });
    const context =
      shell === 'zsh'
        ? `compdef() { :; }; source ${quote(posix(shellScript))}; words=(${quote(posix(binary))} setup --sh --log-level Info); CURRENT=3; _describe() { print -l -- "\${reply[@]}"; }; _craft_completion`
        : `source ${quote(posix(shellScript))}; function commandline; switch $argv[1]; case -opc; printf '%s\\n' ${quote(posix(binary))} setup; case -ct; printf '%s\\n' --sh; end; end; __craft_completion`;
    const result = await execute(shell, ['-c', context], { cwd: root, env });
    assert(
      result.stdout
        .split(/\r?\n/)
        .some(line => line === '--shell' || line.startsWith('--shell:')),
      `${shell} must offer --shell: ${result.stdout}`,
    );
  }
  const commands = (await run(['--get-yargs-completions', 'craft', ''])).stdout;
  assert.match(commands, /prepare/);
  assert.match(commands, /update/);
  console.log(
    `Completion generation, Bash suggestions, setup and dry-run verified: ${platform}`,
  );
} finally {
  await rm(root, { recursive: true, force: true });
}
